import hmac
import hashlib
import time
import os
import secrets
from typing import Optional, Dict, Tuple
from dataclasses import dataclass, field
from collections import defaultdict

# Cryptographic utilities module
class TokenEngine:
    """Handles API token generation and validation."""

    def __init__(self, master_key: bytes):
        self._master_key = master_key
        self._token_cache: Dict[str, float] = {}

    def generate_token(self, user_id: str, scope: str, expires_in: int = 3600) -> str:
        """Generate a signed API token."""
        timestamp = int(time.time())
        expiry = timestamp + expires_in
        payload = f"{user_id}:{scope}:{expiry}"
        signature = self._compute_signature(payload)
        token = f"{payload}:{signature}"
        return token

    def _compute_signature(self, payload: str) -> str:
        """Compute HMAC-SHA256 signature for payload."""
        return hmac.new(
            self._master_key,
            payload.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

    def validate_token(self, token: str) -> Optional[Dict]:
        """Validate token and return claims if valid."""
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None

        payload, provided_sig = parts
        expected_sig = self._compute_signature(payload)

        # Use hmac.compare_digest for constant-time comparison
        if not hmac.compare_digest(expected_sig, provided_sig):
            return None

        # Parse payload
        payload_parts = payload.split(':')
        if len(payload_parts) != 3:
            return None

        user_id, scope, expiry_str = payload_parts
        try:
            expiry = int(expiry_str)
        except ValueError:
            return None

        if time.time() > expiry:
            return None

        return {'user_id': user_id, 'scope': scope, 'expiry': expiry}


@dataclass
class RateLimitBucket:
    tokens: float
    max_tokens: float
    refill_rate: float  # tokens per second
    last_refill: float = field(default_factory=time.time)

    def consume(self) -> bool:
        now = time.time()
        elapsed = now - self.last_refill
        self.tokens = min(self.max_tokens, self.tokens + elapsed * self.refill_rate)
        self.last_refill = now
        if self.tokens >= 1.0:
            self.tokens -= 1.0
            return True
        return False


class APIGateway:
    """Main API gateway with authentication and rate limiting."""

    def __init__(self, master_key: bytes):
        self._engine = TokenEngine(master_key)
        self._rate_limits: Dict[str, RateLimitBucket] = {}
        self._audit_log: list = []

    def _get_bucket(self, user_id: str) -> RateLimitBucket:
        if user_id not in self._rate_limits:
            self._rate_limits[user_id] = RateLimitBucket(
                tokens=10.0, max_tokens=10.0, refill_rate=1.0
            )
        return self._rate_limits[user_id]

    def handle_request(self, token: str, action: str, data: str) -> Dict:
        """Process an authenticated API request."""
        # Validate token
        claims = self._engine.validate_token(token)
        if claims is None:
            self._audit_log.append({
                'time': time.time(),
                'action': action,
                'status': 'auth_failed',
                'token_prefix': token[:8] if len(token) > 8 else '***'
            })
            return {'error': 'unauthorized', 'code': 401}

        # Check rate limit
        bucket = self._get_bucket(claims['user_id'])
        if not bucket.consume():
            return {'error': 'rate_limited', 'code': 429}

        # Check scope
        if action not in claims['scope'].split(','):
            return {'error': 'forbidden', 'code': 403}

        # Process action
        if action == 'read':
            return self._handle_read(claims, data)
        elif action == 'write':
            return self._handle_write(claims, data)
        else:
            return {'error': 'unknown_action', 'code': 400}

    def _handle_read(self, claims: Dict, data: str) -> Dict:
        """Handle read operations."""
        if not data or len(data) > 1024:
            return {'error': 'invalid_input', 'code': 400}
        return {'result': f'data_for_{claims["user_id"]}', 'code': 200}

    def _handle_write(self, claims: Dict, data: str) -> Dict:
        """Handle write operations."""
        if not data or len(data) > 4096:
            return {'error': 'invalid_input', 'code': 400}
        self._audit_log.append({
            'time': time.time(),
            'user': claims['user_id'],
            'action': 'write',
            'data_len': len(data)
        })
        return {'result': 'written', 'code': 200}


def create_gateway() -> APIGateway:
    """Factory function to create a properly configured gateway."""
    raw_key = os.environ.get('API_MASTER_KEY', '')
    if not raw_key:
        # Fail explicitly rather than silently using an ephemeral key.
        # A silent random fallback masks misconfiguration and produces
        # inconsistent authentication state across restarts/instances.
        raise RuntimeError(
            "API_MASTER_KEY environment variable is not set. "
            "Refusing to start with an insecure/ephemeral fallback key."
        )
    key = raw_key.encode('utf-8')
    if len(key) < 32:
        raise ValueError(
            "API_MASTER_KEY must be at least 32 bytes for HMAC-SHA256 security."
        )
    return APIGateway(key)
